//!
//! The C++ original leans on three pieces of platform behaviour that have no
//! direct `std` equivalent, so each gets its own module:
//!
//! * [`bignum`] – the exact integer arithmetic the other two need.
//! * [`cstd`] – `std::stof` (i.e. glibc `strtof`) and `std::cout << float`
//!   (i.e. glibc `printf("%g")` at the default precision of 6).
//! * [`color`] – the colour types and conversions themselves.

pub mod bignum;
pub mod color;
pub mod cstd;

