//! Arbitrary-precision unsigned integers, cut down to exactly the operations
//! needed to convert between binary floats and decimal strings without ever
//! losing a bit.
//!
//! Only a small vocabulary is required: build from a digit run, scale by a
//! power of five or two, divide by a power of five or two while reporting
//! whether anything was dropped, and render back to decimal. Nothing here
//! needs full long division, which is why there is no big-by-big divide.
//!
//! Values are little-endian base-2^32 limbs with no trailing zero limb, so an
//! empty limb vector is zero.

/// 5^13, the largest power of five that fits in a `u32`.
const POW5_13: u32 = 1_220_703_125;
/// 10^9, the largest power of ten that fits in a `u32`.
const POW10_9: u32 = 1_000_000_000;

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct BigUint {
    limbs: Vec<u32>,
}

impl BigUint {
    pub fn zero() -> Self {
        BigUint { limbs: Vec::new() }
    }

    pub fn from_u64(mut v: u64) -> Self {
        let mut limbs = Vec::new();
        while v != 0 {
            limbs.push((v & 0xffff_ffff) as u32);
            v >>= 32;
        }
        BigUint { limbs }
    }

    /// Build from a run of ASCII decimal digits of any length.
    pub fn from_ascii_digits(digits: &[u8]) -> Self {
        let mut n = BigUint::zero();
        let mut i = 0;
        while i < digits.len() {
            // Nine digits at a time: the largest chunk whose value and whose
            // scale both stay inside a u32.
            let take = usize::min(9, digits.len() - i);
            let mut acc: u32 = 0;
            let mut scale: u32 = 1;
            for &d in &digits[i..i + take] {
                acc = acc * 10 + u32::from(d - b'0');
                scale *= 10;
            }
            n.mul_small(scale);
            n.add_small(acc);
            i += take;
        }
        n
    }

    /// Build from a run of ASCII hex digits of any length.
    pub fn from_ascii_hex_digits(digits: &[u8]) -> Self {
        let mut n = BigUint::zero();
        let mut i = 0;
        while i < digits.len() {
            let take = usize::min(8, digits.len() - i);
            let mut acc: u32 = 0;
            for &d in &digits[i..i + take] {
                let v = match d {
                    b'0'..=b'9' => d - b'0',
                    b'a'..=b'f' => d - b'a' + 10,
                    _ => d - b'A' + 10,
                };
                acc = (acc << 4) | u32::from(v);
            }
            n.shl_bits(4 * take as u64);
            n.add_small(acc);
            i += take;
        }
        n
    }

    pub fn is_zero(&self) -> bool {
        self.limbs.is_empty()
    }

    /// Position of the most significant set bit, counting from one; zero for 0.
    pub fn bit_len(&self) -> u64 {
        match self.limbs.last() {
            None => 0,
            Some(&top) => (self.limbs.len() as u64 - 1) * 32 + (32 - u64::from(top.leading_zeros())),
        }
    }

    /// The value as a `u64`, or `None` when it does not fit.
    pub fn to_u64(&self) -> Option<u64> {
        if self.limbs.len() > 2 {
            return None;
        }
        let mut v: u64 = 0;
        for (i, &l) in self.limbs.iter().enumerate() {
            v |= u64::from(l) << (32 * i);
        }
        Some(v)
    }

    fn trim(&mut self) {
        while self.limbs.last() == Some(&0) {
            self.limbs.pop();
        }
    }

    pub fn mul_small(&mut self, m: u32) {
        if m == 0 {
            self.limbs.clear();
            return;
        }
        let mut carry: u64 = 0;
        for l in self.limbs.iter_mut() {
            let p = u64::from(*l) * u64::from(m) + carry;
            *l = (p & 0xffff_ffff) as u32;
            carry = p >> 32;
        }
        while carry != 0 {
            self.limbs.push((carry & 0xffff_ffff) as u32);
            carry >>= 32;
        }
    }

    pub fn add_small(&mut self, a: u32) {
        let mut carry = u64::from(a);
        let mut i = 0;
        while carry != 0 {
            if i == self.limbs.len() {
                self.limbs.push(0);
            }
            let s = u64::from(self.limbs[i]) + carry;
            self.limbs[i] = (s & 0xffff_ffff) as u32;
            carry = s >> 32;
            i += 1;
        }
    }

    /// Divide in place by a small divisor, returning the remainder.
    pub fn div_small(&mut self, d: u32) -> u32 {
        let mut rem: u64 = 0;
        for l in self.limbs.iter_mut().rev() {
            let cur = (rem << 32) | u64::from(*l);
            *l = (cur / u64::from(d)) as u32;
            rem = cur % u64::from(d);
        }
        self.trim();
        rem as u32
    }

    pub fn mul_pow5(&mut self, mut n: u32) {
        while n >= 13 {
            self.mul_small(POW5_13);
            n -= 13;
        }
        if n > 0 {
            self.mul_small(pow5(n));
        }
    }

    /// Divide in place by 5^n; returns true when nothing was dropped.
    ///
    /// Chained floor divisions compose, and the overall division is exact
    /// exactly when every step's remainder was zero.
    pub fn div_pow5(&mut self, mut n: u32) -> bool {
        let mut exact = true;
        while n >= 13 {
            exact &= self.div_small(POW5_13) == 0;
            n -= 13;
        }
        if n > 0 {
            exact &= self.div_small(pow5(n)) == 0;
        }
        exact
    }

    pub fn shl_bits(&mut self, n: u64) {
        if self.is_zero() || n == 0 {
            return;
        }
        let limb_shift = (n / 32) as usize;
        let bit_shift = (n % 32) as u32;
        if bit_shift != 0 {
            let mut carry: u32 = 0;
            for l in self.limbs.iter_mut() {
                let v = (u64::from(*l) << bit_shift) | u64::from(carry);
                *l = (v & 0xffff_ffff) as u32;
                carry = (v >> 32) as u32;
            }
            if carry != 0 {
                self.limbs.push(carry);
            }
        }
        if limb_shift != 0 {
            let mut out = vec![0u32; limb_shift];
            out.extend_from_slice(&self.limbs);
            self.limbs = out;
        }
    }

    /// Shift right in place; returns true when no set bit was discarded.
    pub fn shr_bits(&mut self, n: u64) -> bool {
        if n == 0 {
            return true;
        }
        let limb_shift = (n / 32) as usize;
        let bit_shift = (n % 32) as u32;
        if limb_shift >= self.limbs.len() {
            let exact = self.is_zero();
            self.limbs.clear();
            return exact;
        }
        let mut exact = true;
        for i in 0..limb_shift {
            exact &= self.limbs[i] == 0;
        }
        self.limbs.drain(0..limb_shift);
        if bit_shift != 0 {
            let mask = (1u32 << bit_shift) - 1;
            exact &= self.limbs[0] & mask == 0;
            let mut prev: u32 = 0;
            for l in self.limbs.iter_mut().rev() {
                let v = *l;
                *l = (v >> bit_shift) | (prev << (32 - bit_shift));
                prev = v & mask;
            }
            self.trim();
        }
        exact
    }

    /// Exact decimal rendering; "0" for zero, otherwise no leading zeros.
    pub fn to_decimal_string(&self) -> String {
        if self.is_zero() {
            return "0".to_string();
        }
        let mut n = self.clone();
        let mut chunks: Vec<u32> = Vec::new();
        while !n.is_zero() {
            chunks.push(n.div_small(POW10_9));
        }
        let mut s = chunks.last().unwrap().to_string();
        for &c in chunks.iter().rev().skip(1) {
            s.push_str(&format!("{:09}", c));
        }
        s
    }
}

fn pow5(n: u32) -> u32 {
    let mut p: u32 = 1;
    for _ in 0..n {
        p *= 5;
    }
    p
}

