//! on: `std::stof` (glibc `strtof` plus libstdc++'s error wrapper) and
//! `std::cout << float` (glibc `printf("%g")` at the default precision of 6).

pub mod fmt;
pub mod strtof;

pub use fmt::format_g6;
pub use strtof::{stof, StofError};

