//! `std::stof`, i.e. glibc `strtof` behind libstdc++'s thin error wrapper.
//!
//! libstdc++ clears `errno`, calls `strtof`, and then maps the outcome:
//! nothing converted becomes `std::invalid_argument`, `ERANGE` becomes
//! `std::out_of_range`. Trailing garbage is *not* an error, so `"12abc"`
//! yields 12.
//!
//! That makes three things load-bearing, and all three are reproduced here:
//!
//! 1. The full `strtof` grammar — leading whitespace, sign, decimal, C99 hex
//!    floats, `inf`/`infinity`, `nan` with an optional `(n-char-sequence)` —
//!    accepting the longest valid prefix and stopping there.
//! 2. Correctly rounded conversion. Decimal goes through `std`'s parser, which
//!    is correctly rounded; hex is converted here.
//! 3. glibc's exact `ERANGE` rule. Overflow is simply "the rounded result is
//!    infinite", but underflow has two quirks worth spelling out, both pinned
//!    down against glibc:
//!
//!    * Whether a value counts as subnormal is decided *after* rounding its
//!      significand to 24 bits at the value's own exponent. A value just under
//!      `FLT_MIN` whose rounding carries into the normal range reports no
//!      underflow, even though a value slightly smaller — which rounds to the
//!      very same `FLT_MIN` — does report it.
//!    * When denormalising, the dropped round bit alone is not a "lost bit".
//!      Only bits strictly below it, or bits shifted out of the significand,
//!      count. So a value a quarter of an ulp above a subnormal reports no
//!      underflow while one an eighth of an ulp above it does.

use super::super::bignum::BigUint;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum StofError {
    /// No conversion could be performed (`std::invalid_argument`).
    InvalidArgument,
    /// The value was out of range for a `float` (`std::out_of_range`).
    OutOfRange,
}

impl StofError {
    /// The C++ exception class name, as the terminate handler prints it.
    pub fn exception_name(self) -> &'static str {
        match self {
            StofError::InvalidArgument => "std::invalid_argument",
            StofError::OutOfRange => "std::out_of_range",
        }
    }
}

/// `std::stof(str)`.
pub fn stof(s: &str) -> Result<f32, StofError> {
    let r = strtof(s.as_bytes());
    if r.consumed == 0 {
        return Err(StofError::InvalidArgument);
    }
    if r.erange {
        return Err(StofError::OutOfRange);
    }
    Ok(r.value)
}

pub struct StrtofResult {
    pub value: f32,
    /// Bytes consumed; zero means no conversion (`endptr == nptr`).
    pub consumed: usize,
    /// Whether `strtof` would have set `errno` to `ERANGE`.
    pub erange: bool,
}

fn is_space(c: u8) -> bool {
    matches!(c, b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r')
}

/// Case-insensitive prefix match; returns the match length.
fn match_ci(b: &[u8], pat: &[u8]) -> Option<usize> {
    if b.len() < pat.len() {
        return None;
    }
    for (x, y) in b.iter().zip(pat) {
        if x.to_ascii_lowercase() != *y {
            return None;
        }
    }
    Some(pat.len())
}

fn done(v: f32, neg: bool, consumed: usize, erange: bool) -> StrtofResult {
    StrtofResult {
        value: if neg { -v } else { v },
        consumed,
        erange,
    }
}

pub fn strtof(b: &[u8]) -> StrtofResult {
    let n = b.len();
    let mut i = 0;
    while i < n && is_space(b[i]) {
        i += 1;
    }
    let mut neg = false;
    if i < n && (b[i] == b'+' || b[i] == b'-') {
        neg = b[i] == b'-';
        i += 1;
    }

    // "infinity" is tried first so the longer spelling wins.
    if let Some(len) = match_ci(&b[i..], b"infinity") {
        return done(f32::INFINITY, neg, i + len, false);
    }
    if let Some(len) = match_ci(&b[i..], b"inf") {
        return done(f32::INFINITY, neg, i + len, false);
    }
    if let Some(len) = match_ci(&b[i..], b"nan") {
        let mut j = i + len;
        if j < n && b[j] == b'(' {
            let mut k = j + 1;
            while k < n && (b[k].is_ascii_alphanumeric() || b[k] == b'_') {
                k += 1;
            }
            if k < n && b[k] == b')' {
                j = k + 1;
            }
        }
        return done(f32::NAN, neg, j, false);
    }

    if i + 1 < n && b[i] == b'0' && (b[i + 1] == b'x' || b[i + 1] == b'X') {
        if let Some(r) = parse_hex(b, i + 2, neg) {
            return r;
        }
        // "0x" with no hex digit after it: glibc converts just the "0".
        return done(0.0, neg, i + 1, false);
    }

    parse_dec(b, i, neg)
}

/// Parse `[+-]?digits` for an exponent, clamping far outside any useful range
/// rather than overflowing.
fn parse_exp(b: &[u8], mut i: usize) -> Option<(i64, usize)> {
    let n = b.len();
    let mut neg = false;
    if i < n && (b[i] == b'+' || b[i] == b'-') {
        neg = b[i] == b'-';
        i += 1;
    }
    let start = i;
    while i < n && b[i].is_ascii_digit() {
        i += 1;
    }
    if i == start {
        return None;
    }
    let mut v: i64 = 0;
    for &d in &b[start..i] {
        if v < 1_000_000_000_000 {
            v = v * 10 + i64::from(d - b'0');
        }
    }
    Some((if neg { -v } else { v }, i))
}

fn parse_dec(b: &[u8], start: usize, neg: bool) -> StrtofResult {
    let n = b.len();
    let mut i = start;
    let int_start = i;
    while i < n && b[i].is_ascii_digit() {
        i += 1;
    }
    let int_end = i;
    let mut frac_start = i;
    let mut frac_end = i;
    if i < n && b[i] == b'.' {
        i += 1;
        frac_start = i;
        while i < n && b[i].is_ascii_digit() {
            i += 1;
        }
        frac_end = i;
    }
    if int_end == int_start && frac_end == frac_start {
        return StrtofResult { value: 0.0, consumed: 0, erange: false };
    }
    let mut end = i;
    let mut exp: i64 = 0;
    if i < n && (b[i] == b'e' || b[i] == b'E') {
        if let Some((e, next)) = parse_exp(b, i + 1) {
            exp = e;
            end = next;
        }
    }

    let mut digits: Vec<u8> = Vec::with_capacity((int_end - int_start) + (frac_end - frac_start));
    digits.extend_from_slice(&b[int_start..int_end]);
    digits.extend_from_slice(&b[frac_start..frac_end]);
    let mut k = exp - (frac_end - frac_start) as i64;
    // Normalise to significant digits: leading zeros are free, trailing zeros
    // move into the scale.
    let lead = digits.iter().take_while(|&&d| d == b'0').count();
    digits.drain(0..lead);
    while digits.last() == Some(&b'0') {
        digits.pop();
        k += 1;
    }

    let (value, erange) = decimal_to_f32(&digits, k);
    done(value, neg, end, erange)
}

/// Convert `digits * 10^k` (digits already normalised, no sign) to `f32`,
/// reporting whether glibc would set `ERANGE`.
fn decimal_to_f32(digits: &[u8], k: i64) -> (f32, bool) {
    if digits.is_empty() {
        return (0.0, false); // an exact zero never reports a range error
    }
    let mag = digits.len() as i64 - 1 + k; // floor(log10 V)
    if mag > 60 {
        return (f32::INFINITY, true); // far past FLT_MAX
    }
    if mag < -100 {
        return (0.0, true); // far below the smallest subnormal
    }
    let text = format!("{}e{}", std::str::from_utf8(digits).unwrap(), k);
    let value: f32 = text.parse().unwrap();
    if value.is_infinite() {
        return (value, true);
    }
    // Only a result at or below FLT_MIN can be an underflow, and deciding it
    // needs the exact value rather than the rounded one.
    let erange = value.abs() <= f32::MIN_POSITIVE && decimal_underflow(digits, k, mag);
    (value, erange)
}

enum Q2 {
    TooSmall,
    TooLarge,
    Ok(u64),
}

/// `floor(V * 2^(24-e))` must land in `[2^24, 2^25)` for `e` to be `V`'s own
/// binary exponent.
fn classify(q2: &BigUint) -> Q2 {
    match q2.to_u64() {
        None => Q2::TooLarge,
        Some(v) if v < 1 << 24 => Q2::TooSmall,
        Some(v) if v >= 1 << 25 => Q2::TooLarge,
        Some(v) => Q2::Ok(v),
    }
}

/// `floor(V * 2^(24-e))` for `V = d * 10^-j`, with a flag for exactness.
///
/// `V * 2^(24-e) = d * 2^(24-e-j) / 5^j`, and chained floor divisions compose,
/// so dividing by `5^j` and by a power of two in either order is still exact.
fn extract_dec(d: &BigUint, j: u32, e: i64) -> (BigUint, bool) {
    let t = 24 - e - i64::from(j);
    let mut n = d.clone();
    if t >= 0 {
        n.shl_bits(t as u64);
        let exact = n.div_pow5(j);
        (n, exact)
    } else {
        let by_five = n.div_pow5(j);
        let by_two = n.shr_bits((-t) as u64);
        (n, by_five && by_two)
    }
}

fn decimal_underflow(digits: &[u8], k: i64, mag: i64) -> bool {
    if k >= 0 {
        return false; // the value is an integer, so at least 1
    }
    let j = (-k) as u32;
    let d = BigUint::from_ascii_digits(digits);
    // log2(10) * mag lands within a few of the true exponent; the loop below
    // walks the rest of the way.
    let mut e = (mag as f64 * 3.321_928_094_887_362_f64).floor() as i64;
    loop {
        let (q2, exact) = extract_dec(&d, j, e);
        match classify(&q2) {
            Q2::TooSmall => e -= 1,
            Q2::TooLarge => e += 1,
            Q2::Ok(v) => {
                return glibc_underflow((v >> 1) as u32, e, v & 1 == 1, !exact);
            }
        }
    }
}

/// glibc's underflow rule, given the truncated 24-bit significand `q` at
/// exponent `e` plus the round and sticky bits below it.
fn glibc_underflow(q: u32, e: i64, round: bool, sticky: bool) -> bool {
    let up = round && (sticky || q & 1 == 1);
    // Normal-vs-subnormal is decided after this rounding, so a carry out of
    // the significand escapes the report entirely.
    let e1 = if q + u32::from(up) == 1 << 24 { e + 1 } else { e };
    if e1 >= -126 {
        return false;
    }
    let shift = -126 - e1;
    if shift >= 24 {
        return true;
    }
    // The round bit itself does not count as a lost bit here — only bits
    // strictly below it, or bits shifted out of the significand.
    q & ((1u32 << shift) - 1) != 0 || sticky
}

fn parse_hex(b: &[u8], start: usize, neg: bool) -> Option<StrtofResult> {
    let n = b.len();
    let mut i = start;
    let int_start = i;
    while i < n && b[i].is_ascii_hexdigit() {
        i += 1;
    }
    let int_end = i;
    let mut frac_start = i;
    let mut frac_end = i;
    if i < n && b[i] == b'.' {
        i += 1;
        frac_start = i;
        while i < n && b[i].is_ascii_hexdigit() {
            i += 1;
        }
        frac_end = i;
    }
    if int_end == int_start && frac_end == frac_start {
        return None;
    }
    let mut end = i;
    let mut pexp: i64 = 0;
    if i < n && (b[i] == b'p' || b[i] == b'P') {
        if let Some((e, next)) = parse_exp(b, i + 1) {
            pexp = e;
            end = next;
        }
    }

    let mut digits: Vec<u8> = Vec::with_capacity((int_end - int_start) + (frac_end - frac_start));
    digits.extend_from_slice(&b[int_start..int_end]);
    digits.extend_from_slice(&b[frac_start..frac_end]);
    let m = BigUint::from_ascii_hex_digits(&digits);
    let he = pexp - 4 * (frac_end - frac_start) as i64;

    let (value, erange) = hex_to_f32(&m, he);
    Some(done(value, neg, end, erange))
}

/// Convert the exact value `m * 2^he` to `f32`, reporting `ERANGE`.
fn hex_to_f32(m: &BigUint, he: i64) -> (f32, bool) {
    if m.is_zero() {
        return (0.0, false);
    }
    let bits = m.bit_len() as i64;
    let e = bits - 1 + he;
    // V * 2^(24-e) = m * 2^(25 - bit_len), independent of `he`, so no huge
    // shift even for an absurd `p` exponent.
    let t = 25 - bits;
    let mut q2 = m.clone();
    let exact = if t >= 0 {
        q2.shl_bits(t as u64);
        true
    } else {
        q2.shr_bits((-t) as u64)
    };
    let v = q2.to_u64().expect("25 bits by construction");
    round_to_f32((v >> 1) as u32, e, v & 1 == 1, !exact)
}

/// Round the exact value described by `(q, e, round, sticky)` to `f32`, and
/// report `ERANGE`.
fn round_to_f32(q: u32, e: i64, round: bool, sticky: bool) -> (f32, bool) {
    let up = round && (sticky || q & 1 == 1);
    let mut q1 = q + u32::from(up);
    let mut e1 = e;
    if q1 == 1 << 24 {
        q1 >>= 1;
        e1 += 1;
    }
    if e1 > 127 {
        return (f32::INFINITY, true);
    }
    if e1 >= -126 {
        let bits = (((e1 + 127) as u32) << 23) | (q1 & 0x7f_ffff);
        return (f32::from_bits(bits), false);
    }
    let shift = -126 - e1;
    if shift >= 25 {
        return (0.0, true); // below half the smallest subnormal
    }
    let shift = shift as u32;
    let mask = (1u32 << shift) - 1;
    let lost = shift >= 24 || q & mask != 0 || sticky;
    let hi = q >> shift;
    let low = q & mask;
    let half = 1u32 << (shift - 1);
    let up2 = if low > half {
        true
    } else if low < half {
        false
    } else {
        round || sticky || hi & 1 == 1
    };
    // A subnormal significand of 2^23 encodes FLT_MIN, so no special case is
    // needed when rounding carries out of the subnormal range.
    (f32::from_bits(hi + u32::from(up2)), lost)
}

