//! Port of `tests/test13.cpp`: print the hue difference between two HSL colours.
//!
//! Argument handling mirrors the original exactly, including the two-step
//! check: five or more arguments replace the first five defaults, and a sixth
//! is needed before `l2` is read. Every argument is parsed with `std::stof`
//! semantics, so a bad or out-of-range one aborts the way the C++ binary does —
//! even for the components the result does not depend on.

#[path = "src/lib.rs"]
mod colorspace;

use colorspace::color::{ColorConverter, Hsl};
use colorspace::cstd::{format_g6, stof, StofError};

/// Stand in for an uncaught C++ exception: the terminate handler's message on
/// stderr, then `SIGABRT`.
fn terminate(err: StofError) -> ! {
    use std::io::Write;
    let mut err_out = std::io::stderr();
    let _ = write!(
        err_out,
        "terminate called after throwing an instance of '{}'\n  what():  stof\n",
        err.exception_name()
    );
    let _ = err_out.flush();
    std::process::abort()
}

fn parse(arg: &str) -> f32 {
    match stof(arg) {
        Ok(v) => v,
        Err(e) => terminate(e),
    }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let argc = args.len();

    let (mut h1, mut s1, mut l1) = (30.0f32, 0.6f32, 0.5f32);
    let (mut h2, mut s2, mut l2) = (210.0f32, 0.4f32, 0.7f32);

    if argc > 5 {
        h1 = parse(&args[1]);
        s1 = parse(&args[2]);
        l1 = parse(&args[3]);
        h2 = parse(&args[4]);
        s2 = parse(&args[5]);
    }
    if argc > 6 {
        l2 = parse(&args[6]);
    }

    let hsl1 = Hsl::new(h1 as f64, s1 as f64, l1 as f64);
    let hsl2 = Hsl::new(h2 as f64, s2 as f64, l2 as f64);

    let hue_diff = ColorConverter::hue_difference(&hsl1, &hsl2) as f32;

    println!("{}", format_g6(hue_diff));
}

